import { readFileSync, writeFileSync, readdirSync } from 'fs'
import { join, dirname } from 'path'
import { fileURLToPath } from 'url'

const __dirname = dirname(fileURLToPath(import.meta.url))
const godsDir = join(__dirname, '..', 'src', 'data', 'gods')

const translations = {
  Ashenzari: {
    description_en: "While it seems inconceivable that the divine could be shackled, Ashenzari is just that: bound to the sky for eternity, the unbudging god is all-knowing, all-seeing. Devoted worshippers are allowed to grasp shreds of this knowledge and foresight, but be warned: to Ashenzari, power and blessing and curse are all the same thing.",
    description_es_mt: "Aunque parezca inconcebible que lo divino pueda estar encadenado, Ashenzari es exactamente eso: atado al cielo por la eternidad, el dios inmutable lo sabe todo, lo ve todo. A los devotos adoradores se les permite captar fragmentos de este conocimiento y previsión, pero cuidado: para Ashenzari, el poder, la bendición y la maldición son lo mismo.",
    powers_en: "Ashenzari exhorts followers to curse their possessions, periodically offering these curses to worshippers as they explore. These curses grant improvements to specific skills, but cursed equipment cannot normally be enchanted and can only be removed by shattering it forever. As worshippers equip more cursed equipment, Ashenzari will grant increasing knowledge of the surrounding dungeon. Eventually, Ashenzari will reveal the invisible, grant clarity of mind, and protect worshippers from the Dungeon's malevolent forces.",
    powers_es_mt: "Ashenzari exhorta a sus seguidores a maldecir sus pertenencias, ofreciendo periódicamente estas maldiciones a los adoradores mientras exploran. Estas maldiciones otorgan mejoras a habilidades específicas, pero el equipo maldito no puede ser encantado y solo se puede eliminar destruyéndolo para siempre. A medida que los adoradores equipan más equipo maldito, Ashenzari les otorga mayor conocimiento de la mazmorra circundante. Eventualmente, Ashenzari revelará lo invisible, concederá claridad mental y protegerá a los adoradores de las fuerzas malévolas de la mazmorra.",
    wrath_en: "Those who abandon Ashenzari will immediately have their curses shattered, destroying whichever items they imbued with divine wisdom. Thereafter, Ashenzari's wrath is constant and unrelenting for its duration. Victims will find their skills impaired, and their enemies divinely guided – never losing track of them, never ending the hunt.",
    wrath_es_mt: "Quienes abandonen a Ashenzari verán sus maldiciones destruidas inmediatamente, perdiendo los objetos que imbuyeron con sabiduría divina. A partir de entonces, la ira de Ashenzari es constante e implacable durante su duración. Las víctimas encontrarán sus habilidades disminuidas y sus enemigos guiados divinamente, sin perderles el rastro ni terminar la cacería."
  },
  Beogh: {
    description_en: "A god of outcasts, pariahs, and the dispossessed, Beogh's altars are rarely found among those of other faiths, but Beogh's missionaries may always be sought by those looking for a place to belong. Worshippers will find many friends within the dungeon, and those who prove their strength to Beogh may gain lifelong companions the equal of any adventurer. To worship Beogh is to believe there is strength that transcends species and bloodline. To worship Beogh is to be an orc.",
    description_es_mt: "Un dios de los marginados, parias y desposeídos, los altares de Beogh rara vez se encuentran entre los de otras fes, pero los misioneros de Beogh siempre pueden ser buscados por aquellos que buscan un lugar al que pertenecer. Los adoradores encontrarán muchos amigos en la mazmorra, y aquellos que demuestren su fuerza a Beogh pueden ganar compañeros de por vida comparables a cualquier aventurero. Adorar a Beogh es creer que hay una fuerza que trasciende la especie y el linaje. Adorar a Beogh es ser un orco.",
    powers_en: "Worshippers will gain the power to call down Beogh's wrath upon their oppressors, and other orcs will start to see them as one of their own. Especially promising adherents will find themselves beset by rivals for Beogh's favour, but overcoming these trials without fleeing will gain them loyal companions whom Beogh will resurrect time and time again, so long as they continue to fight and avenge in Beogh's name. A true chosen one may even rally an entire orcish army to avenge a wrongful death.",
    powers_es_mt: "Los adoradores obtendrán el poder de invocar la ira de Beogh sobre sus opresores, y otros orcos comenzarán a verlos como uno de los suyos. Los adeptos especialmente prometedores se verán acosados por rivales por el favor de Beogh, pero superar estas pruebas sin huir les ganará compañeros leales a quienes Beogh resucitará una y otra vez, siempre que sigan luchando y vengando en nombre de Beogh. Un verdadero elegido puede incluso reunir a todo un ejército orco para vengar una muerte injusta.",
    wrath_en: "Blasphemers against the word of Beogh find themselves assaulted by waves of orcish warriors, or by dancing electric weapons. Beogh may also simply smite such blasphemers – and when smiting true sinners, Beogh has a heavy hand indeed! Those who still worship Beogh will also find their followers regularly deserting them.",
    wrath_es_mt: "Los blasfemos contra la palabra de Beogh se ven asaltados por oleadas de guerreros orcos o por armas eléctricas danzantes. Beogh también puede simplemente fulminar a tales blasfemos, ¡y cuando castiga a verdaderos pecadores, Beogh tiene mano dura! Aquellos que todavía adoran a Beogh también encontrarán que sus seguidores los abandonan regularmente."
  },
  Cheibriados: {
    description_en: "Cheibriados is a god of deliberation. Those following Cheibriados travel more slowly the further they progress in their faith, and are forbidden from using any means to hasten themselves. In the process of so imitating their god, they attain perfection of mind and body, and the mysteries of time unfold before them. Especially devout followers may even momentarily abandon the flow of time and its needless disturbances.",
    description_es_mt: "Cheibriados es un dios de la deliberación. Aquellos que siguen a Cheibriados viajan más lentamente a medida que progresan en su fe, y tienen prohibido usar cualquier medio para apresurarse. En el proceso de imitar a su dios, alcanzan la perfección de mente y cuerpo, y los misterios del tiempo se despliegan ante ellos. Los seguidores especialmente devotos pueden incluso abandonar momentáneamente el flujo del tiempo y sus innecesarias perturbaciones.",
    powers_en: "Followers of Cheibriados move more slowly as they gain favour. As they move slower, worshippers of Cheibriados are granted increased attributes. Cheibriados rewards the faithful with the power to slow other creatures and the power to briefly distort the flow of time. Devout worshippers will gain the ability to inflict great harm on all those who move more quickly than they do, and finally the ability to step out of the flow of time entirely.",
    powers_es_mt: "Los seguidores de Cheibriados se mueven más lentamente a medida que ganan favor. Al moverse más lento, los adoradores de Cheibriados obtienen atributos incrementados. Cheibriados recompensa a los fieles con el poder de ralentizar a otras criaturas y el poder de distorsionar brevemente el flujo del tiempo. Los devotos adoradores ganarán la capacidad de infligir gran daño a todos aquellos que se muevan más rápido que ellos, y finalmente la capacidad de salir completamente del flujo del tiempo.",
    wrath_en: "Offenders against Cheibriados will find their movements remain slow while the attention of Cheibriados remains upon them, and may have any magical hasting stripped away. They may also become further slowed, be put to sleep, or be beset by the unparalleled volume of the inevitable passage of time ringing throughout the Dungeon.",
    wrath_es_mt: "Los infractores contra Cheibriados encontrarán que sus movimientos siguen siendo lentos mientras la atención de Cheibriados permanezca sobre ellos, y pueden perder cualquier aceleración mágica. También pueden volverse aún más lentos, ser puestos a dormir o ser acosados por el volumen incomparable del inevitable paso del tiempo resonando por toda la mazmorra."
  },
  Dithmenos: {
    description_en: "Dithmenos is the god of night and of things half-seen in flickering torchlight. Worshipped by actors as often as thieves, followers of Dithmenos can learn to control their own shadow as if it were an extension of their body - misdirecting onlookers and acting upon the world with force as tangible as anything that has ever been imagined lurking in the dark.",
    description_es_mt: "Dithmenos es el dios de la noche y de las cosas medio vistas en la luz titilante de las antorchas. Adorado tanto por actores como por ladrones, los seguidores de Dithmenos pueden aprender a controlar su propia sombra como si fuera una extensión de su cuerpo, desorientando a los espectadores y actuando sobre el mundo con una fuerza tan tangible como cualquier cosa que se haya imaginado acechando en la oscuridad.",
    powers_en: "Followers of Dithmenos are surrounded by an unnatural quiet, which helps the sounds they make go unnoticed. As they rise in devotion, they will find their own shadow begins to imitate some of their actions, attacking when they attack and even casting shadowy magics that mimic the form - if not the substance - of whichever schools of magic they had been utilising. More devout worshippers additionally gain the ability to swap places with their shadow to mislead enemies, grasp other beings' shadows to unleash their magic on the worshipper's behalf, and finally call down a night so dark that it hides all denizens of the dungeon from each other.",
    powers_es_mt: "Los seguidores de Dithmenos están rodeados por un silencio antinatural que ayuda a que los sonidos que hacen pasen desapercibidos. A medida que aumentan su devoción, descubren que su propia sombra comienza a imitar algunas de sus acciones, atacando cuando ellos atacan e incluso lanzando magias sombrías que imitan la forma, si no la sustancia, de las escuelas de magia que han estado utilizando. Los adoradores más devotos obtienen además la capacidad de intercambiar lugares con su sombra para engañar a los enemigos, agarrar las sombras de otros seres para lanzar su magia en nombre del adorador y finalmente convocar una noche tan oscura que oculta a todos los habitantes de la mazmorra entre sí.",
    wrath_en: "When angered, Dithmenos turns the shadows against victims. Monsters emerge from the darkness, both illusions woven from shadow and the very shadow themselves turning against sinners. Dithmenos' subtle punishments are, if anything, more dangerous: victims find the shadows ripped away from them, hunted with nowhere to hide; or find themselves smothered in shadow and sleeping, perhaps forever.",
    wrath_es_mt: "Cuando se enfada, Dithmenos vuelve las sombras contra las víctimas. Los monstruos emergen de la oscuridad, tanto ilusiones tejidas de sombra como las propias sombras se vuelven contra los pecadores. Los castigos sutiles de Dithmenos son, si acaso, más peligrosos: las víctimas se encuentran despojadas de sus sombras, cazadas sin escondite, o se encuentran asfixiadas en sombras y durmiendo, quizás para siempre."
  },
  Elyvilon: {
    description_en: "Elyvilon the Healer welcomes all kind souls prepared to help others. Those individuals can expect to gain powerful healing abilities, by which they can avoid bloodshed. Elyvilon appreciates exploration of the dungeon. Elyvilon's followers can convert to the Shining One or Zin while keeping some piety.",
    description_es_mt: "Elyvilon la Curandera acoge a todas las almas bondadosas dispuestas a ayudar a los demás. Esas personas pueden esperar obtener poderosas habilidades de curación, con las que pueden evitar el derramamiento de sangre. Elyvilon aprecia la exploración de la mazmorra. Los seguidores de Elyvilon pueden convertirse al Resplandeciente o a Zin conservando algo de piedad.",
    powers_en: "The Healer offers followers a number of means to heal themselves from damage and other ill effects. Followers may also attempt to pacify hostile monsters and turn them neutral. Elyvilon may directly intervene to save a follower's life, and if there has been no such intervention recently, is sure to prevent a killing blow against especially pious followers. Elyvilon may also occasionally protect the follower's allies from death.",
    powers_es_mt: "La Curandera ofrece a sus seguidores varios medios para curarse de daños y otros efectos negativos. Los seguidores también pueden intentar pacificar monstruos hostiles y volverlos neutrales. Elyvilon puede intervenir directamente para salvar la vida de un seguidor, y si no ha habido tal intervención recientemente, seguramente evitará un golpe mortal contra seguidores especialmente piadosos. Elyvilon también puede ocasionalmente proteger a los aliados del seguidor de la muerte.",
    wrath_en: "Elyvilon is not a god known for wrath. Still, those earning Elyvilon's ire will find the Healer occasionally protecting their foes from their attacks, and even from death.",
    wrath_es_mt: "Elyvilon no es un dios conocido por su ira. Aun así, quienes se ganen la ira de Elyvilon descubrirán que la Curandera ocasionalmente protege a sus enemigos de sus ataques, e incluso de la muerte."
  },
  Fedhas: {
    description_en: "Fedhas is the god of plant and fungal life. Followers are prevented from harming any species under Fedhas' protection. In return, Fedhas grants a number of abilities that promote the growth of plants and fungi. These abilities may incidentally prove useful to adventurers.",
    description_es_mt: "Fedhas es el dios de la vida vegetal y fúngica. Los seguidores tienen prohibido dañar cualquier especie bajo la protección de Fedhas. A cambio, Fedhas otorga varias habilidades que promueven el crecimiento de plantas y hongos. Estas habilidades pueden resultar incidentalmente útiles para los aventureros.",
    powers_en: "Plants and fungi will not attack Fedhas' worshippers without provocation. Worshippers may walk through plants or fungi, and even fire missiles or spells through them without causing harm. Fedhas grants powers to temporarily grow a menagerie of plant allies whose strength and duration increase with Invocations skill. Worshippers may grow a protective wall of briar patches as well as ballistomycetes that fire damaging spores whose explosions confuse living creatures. Devout followers can overgrow a stretch of solid terrain with a cluster of plant allies or even summon a mighty oklob plant.",
    powers_es_mt: "Las plantas y los hongos no atacarán a los adoradores de Fedhas sin provocación. Los adoradores pueden caminar a través de plantas u hongos, e incluso disparar proyectiles o hechizos a través de ellos sin causar daño. Fedhas concede poderes para hacer crecer temporalmente una variedad de aliados vegetales cuya fuerza y duración aumentan con la habilidad de Invocaciones. Los adoradores pueden cultivar un muro protector de zarzas y balistomicetos que disparan esporas dañinas cuyas explosiones confunden a las criaturas vivientes. Los devotos seguidores pueden cubrir un tramo de terreno sólido con un grupo de aliados vegetales o incluso invocar una poderosa planta oklob.",
    wrath_en: "Those who offend Fedhas will find the forces of nature invoked against them through a dramatic increase in greenery. They may find themselves transmuted into the plants they have forsaken, or surrounded by impenetrable walls of briars plus vicious acid-spitting oklob plants.",
    wrath_es_mt: "Quienes ofendan a Fedhas descubrirán que las fuerzas de la naturaleza se invocan contra ellos a través de un aumento dramático de la vegetación. Pueden encontrarse transformados en las plantas que han abandonado, o rodeados de muros impenetrables de zarzas y plantas oklob que escupen ácido."
  },
  Gozag: {
    description_en: "Gozag Ym Sagoz the Greedy teaches that the world belongs to the rich. Those accepting this principle may exchange their gold for divine assistance. Followers of Gozag do not earn piety; the only way to impress this god is by amassing a fortune, and worshippers may request as much assistance as they can afford. Fortunately, Gozag's worshippers are said to have the touch of gold.",
    description_es_mt: "Gozag Ym Sagoz el Codicioso enseña que el mundo pertenece a los ricos. Quienes acepten este principio pueden intercambiar su oro por asistencia divina. Los seguidores de Gozag no ganan piedad; la única forma de impresionar a este dios es acumulando una fortuna, y los adoradores pueden solicitar tanta ayuda como puedan pagar. Afortunadamente, se dice que los adoradores de Gozag tienen el toque del oro.",
    powers_en: "For Gozag, both flesh and spirit are inferior to wealth, and therefore all monsters are turned to gold upon death. Other monsters may then be briefly distracted by imaginings of great wealth. Stalwarts can purchase immediate help in the form of potions, and may also pay to attract shopkeepers into the dungeon. Particularly well-off adherents may bribe the inhabitants of a branch of the dungeon to turn a blind eye to their presence, or even to change their allegiance.",
    powers_es_mt: "Para Gozag, tanto la carne como el espíritu son inferiores a la riqueza, y por lo tanto todos los monstruos se convierten en oro al morir. Otros monstruos pueden distraerse brevemente imaginando grandes riquezas. Los fieles pueden comprar ayuda inmediata en forma de pociones, y también pueden pagar para atraer comerciantes a la mazmorra. Los adeptos particularmente acaudalados pueden sobornar a los habitantes de una rama de la mazmorra para que ignoren su presencia, o incluso cambiar su lealtad.",
    wrath_en: "The first of Gozag's punishments is commercial: all shops opened through Gozag's intervention shut their doors forever. The disloyal are advised to finish their shopping before they launch their betrayal. For as long as Gozag remains angered, ex-worshippers may sometimes be bedazzled by the glint of coin, and their potions will have a chance to fail when quaffed. Any foes that are encountered may also be granted potions of their own to assist them against those who resign from Gozag's service.",
    wrath_es_mt: "El primer castigo de Gozag es comercial: todas las tiendas abiertas por intervención de Gozag cierran sus puertas para siempre. Se aconseja a los desleales que terminen sus compras antes de lanzar su traición. Mientras Gozag permanezca enfadado, los ex adoradores pueden verse deslumbrados por el brillo de las monedas, y sus pociones pueden fallar al beberlas. Cualquier enemigo encontrado puede recibir pociones propias para ayudarles contra quienes renuncian al servicio de Gozag."
  },
  Hepliaklqana: {
    description_en: "Hepliaklqana the Forgotten accepts the worship of those who would remember their forebears, and fight alongside the greatest of them all. Acolytes of Hepliaklqana sacrifice a small part of their life essence to manifest their ancestor into the world; as they explore and form new experiences, they will find themselves able to shape and control their ancestor's memory, eventually bringing them into the ranks of the mythical heroes.",
    description_es_mt: "Hepliaklqana el Olvidado acepta la adoración de aquellos que recuerdan a sus antepasados y luchan junto al más grande de ellos. Los acólitos de Hepliaklqana sacrifican una pequeña parte de su esencia vital para manifestar a su ancestro en el mundo; a medida que exploran y forman nuevas experiencias, descubrirán que pueden moldear y controlar la memoria de su ancestro, llevándolo eventualmente a las filas de los héroes míticos.",
    powers_en: "Hepliaklqana's worshippers are served by a guardian formed from a part of their life essence, in the shape of their greatest ancestor. This ancestor is at first remembered as they were at the start of their fabled adventures, but will advance in skill as their descendant does. Hepliaklqana always allows followers to recall their ancestor to their side, and, even if the ancestor is destroyed, Hepliaklqana will call it forth again not long after. Further advancement in Hepliaklqana's service allows worshippers to restore and strengthen their ancestor, to swap them with other creatures, and to choose how to remember their life's talents.",
    powers_es_mt: "Los adoradores de Hepliaklqana son servidos por un guardián formado a partir de una parte de su esencia vital, con la forma de su mayor antepasado. Este ancestro es recordado al principio como estaba al inicio de sus fabulosas aventuras, pero avanzará en habilidad a medida que lo haga su descendiente. Hepliaklqana siempre permite a los seguidores recordar a su ancestro para que vuelva a su lado, e incluso si el ancestro es destruido, Hepliaklqana lo convocará de nuevo poco después. Un mayor avance en el servicio de Hepliaklqana permite a los adoradores restaurar y fortalecer a su ancestro, intercambiarlo con otras criaturas y elegir cómo recordar los talentos de su vida.",
    wrath_en: "Hepliaklqana believes that the only reasonable punishment for turning one's back on the path of memory is to be denied its use. All new experience is denied to the unfortunate apostate, until Hepliaklqana decides they have been punished enough. The life essence sacrificed to manifest an ancestor will not be returned until Hepliaklqana is mollified, and this will not be quick: unlike some, Hepliaklqana has a long memory.",
    wrath_es_mt: "Hepliaklqana cree que el único castigo razonable para quien abandona el camino de la memoria es negarle su uso. Toda nueva experiencia le es negada al desafortunado apóstata, hasta que Hepliaklqana decida que ha sido castigado lo suficiente. La esencia vital sacrificada para manifestar un ancestro no será devuelta hasta que Hepliaklqana se apacigüe, y esto no será rápido: a diferencia de algunos, Hepliaklqana tiene memoria larga."
  },
  Ignis: {
    description_en: "Ignis the Dying Flame offers followers power over fire in many forms. All of Ignis' power is offered unconditionally to any who would deign to worship, but once used, it can never be replenished. Ignis' other worshippers deserted long ago; the divine fire burns low, and soon it will go out.",
    description_es_mt: "Ignis la Llama Moribunda ofrece a sus seguidores poder sobre el fuego en muchas formas. Todo el poder de Ignis se ofrece incondicionalmente a cualquiera que se digne a adorarlo, pero una vez usado, nunca puede ser repuesto. Los otros adoradores de Ignis desertaron hace mucho tiempo; el fuego divino arde débilmente, y pronto se apagará.",
    powers_en: "Followers can armour themselves in flame, call a swarm of foxfires against their foes, or let Ignis' heat lift them to another level of the dungeon. However, the guttering flames of Ignis' power will only sustain a limited number of invocations before only flickering embers remain. No matter how depleted, Ignis will always grant followers resistance to fire.",
    powers_es_mt: "Los seguidores pueden armarse de llamas, invocar un enjambre de fuegos zorros contra sus enemigos, o dejar que el calor de Ignis los eleve a otro nivel de la mazmorra. Sin embargo, las vacilantes llamas del poder de Ignis solo sostendrán un número limitado de invocaciones antes de que solo queden brasas parpadeantes. No importa cuán agotado esté, Ignis siempre concederá a sus seguidores resistencia al fuego.",
    wrath_en: "The wrath of Ignis is now weaker than that of most other gods. Apostates will find their resistance to fire stripped away completely, and will be periodically assaulted by fire elementals, find their enemies strengthened by fire, or even have the floor burned out from beneath them. Experienced and cautious adventurers will likely overmaster these assaults.",
    wrath_es_mt: "La ira de Ignis es ahora más débil que la de la mayoría de los otros dioses. Los apóstatas perderán completamente su resistencia al fuego, y serán asaltados periódicamente por elementales de fuego, verán a sus enemigos fortalecidos por el fuego, o incluso tendrán el suelo quemado bajo sus pies. Los aventureros experimentados y cautelosos probablemente superarán estos asaltos."
  },
  Jiyva: {
    description_en: "Jiyva is the ancient deity of the slimes. Followers are expected to support the spread and satiation of their fellow slimes by allowing them to consume items, and are prevented from harming any slimes. Especially favoured followers will become as shapeless as their god, mutating wildly.",
    description_es_mt: "Jiyva es la antigua deidad de los limos. Se espera que los seguidores apoyen la propagación y saciedad de sus compañeros limos permitiéndoles consumir objetos, y tienen prohibido dañar a cualquier limo. Los seguidores especialmente favorecidos se volverán tan informes como su dios, mutando salvajemente.",
    powers_en: "Jiyva will gradually fill the dungeon with jellies. These and any other fellow slimes will rapidly consume nearby items, as well as slowly consuming items from elsewhere in the dungeon. As they spread slime across more of the dungeon, Jiyva will grant followers increasingly rapid health and magic regeneration, and will begin mutating them to better reflect Jiyva's image. Followers will later become able to call forth acidic ooze from the walls of the dungeon, and to turn monsters to slime with a touch.",
    powers_es_mt: "Jiyva llenará gradualmente la mazmorra de gelatinas. Estas y cualquier otro limo compañero consumirán rápidamente los objetos cercanos, además de consumir lentamente objetos de otras partes de la mazmorra. A medida que extienden el limo por más partes de la mazmorra, Jiyva otorgará a los seguidores una regeneración de salud y magia cada vez más rápida, y comenzará a mutarlos para reflejar mejor la imagen de Jiyva. Los seguidores más tarde podrán invocar ácido de las paredes de la mazmorra y convertir monstruos en limo con un toque.",
    wrath_en: "Jiyva's vengeance is swift and gurgling. All slimes turn against those who offend Jiyva, and Jiyva ensures a plentiful supply of further slimes. Victims, too, will find their own bodies becoming unstable; acquiring debilitating mutations or contamination, as well as having any gifts of slime mutations stripped away from them.",
    wrath_es_mt: "La venganza de Jiyva es rápida y gorgoteante. Todos los limos se vuelven contra quienes ofenden a Jiyva, y Jiyva asegura un suministro abundante de más limos. Las víctimas también encontrarán que sus propios cuerpos se vuelven inestables, adquiriendo mutaciones debilitantes o contaminación, además de perder cualquier don de mutaciones de limo."
  },
  Kikubaaqudgha: {
    description_en: "Kikubaaqudgha is a terrible Demon-God, served by those who wish to indulge in the powers of death. An evil god, Kikubaaqudgha requires worshippers to cause the death and destruction of as many creatures as possible. In exchange, Kikubaaqudgha offers great assistance to the aspiring necromancer: a supply of useful bodies, knowledge of dark magic, and protection against necromantic backlash.",
    description_es_mt: "Kikubaaqudgha es un terrible dios demonio, servido por aquellos que desean entregarse a los poderes de la muerte. Un dios maligno, Kikubaaqudgha exige que sus adoradores causen la muerte y destrucción de tantas criaturas como sea posible. A cambio, Kikubaaqudgha ofrece gran asistencia al aspirante a nigromante: un suministro de cuerpos útiles, conocimiento de la magia oscura y protección contra las reacciones necrománticas.",
    powers_en: "Kikubaaqudgha will enhance servants' necromantic prowess with gifts of Necromancy spells. Kikubaaqudgha will protect followers from the effects of necromantic miscasts and death curses, and may even shield them from unholy torment. Followers can unearth dying wretches as necromantic fodder, and may invoke the sign of ruin to harm their enemies. Kikubaaqudgha will eventually allow followers to either receive knowledge of the most forbidden necromantic magic, or to have their weapon imbued with pain.",
    powers_es_mt: "Kikubaaqudgha mejorará la destreza necromántica de sus sirvientes con dones de hechizos de Nigromancia. Kikubaaqudgha protegerá a los seguidores de los efectos de los fallos necrománticos y las maldiciones de muerte, e incluso puede protegerlos del tormento profano. Los seguidores pueden desenterrar miserables moribundos como forraje necromántico e invocar el signo de la ruina para dañar a sus enemigos. Kikubaaqudgha eventualmente permitirá a los seguidores recibir conocimiento de la magia necromántica más prohibida, o imbuir su arma con dolor.",
    wrath_en: "Kikubaaqudgha's wrath brings forth all the dread powers of necromancy. Victims may witness the devastating Sign of Ruin form upon themselves, or both doomed and drained without any respect for their negative energy resistance. Furthermore, Kikubaaqudgha's gifts become tainted: the dead rise again as foes, and those that attempt to use necromantic magic to fend off wrath will find it backfiring on them when least expected.",
    wrath_es_mt: "La ira de Kikubaaqudgha desata todos los temibles poderes de la nigromancia. Las víctimas pueden presenciar el devastador Signo de la Ruina formándose sobre ellas, o ser condenadas y drenadas sin respeto por su resistencia a la energía negativa. Además, los dones de Kikubaaqudgha se contaminan: los muertos se levantan de nuevo como enemigos, y aquellos que intenten usar magia necromántica para defenderse de la ira descubrirán que les sale el tiro por la culata cuando menos lo esperan."
  },
  Lugonu: {
    description_en: "Banished to the chaotic realm of the Abyss, Lugonu the Unformed seeks followers to spread bloodshed and corruption in the overworld. Those who gain Lugonu's favour will be granted some of the power of the Abyss itself, allowing them to call forth eldritch horrors, and even to travel between the overworld and the Abyss at will.",
    description_es_mt: "Desterrado al reino caótico del Abismo, Lugonu el Informe busca seguidores para extender el derramamiento de sangre y la corrupción en el mundo superior. Quienes ganen el favor de Lugonu recibirán algo del poder del Abismo mismo, permitiéndoles invocar horrores sobrenaturales e incluso viajar entre el mundo superior y el Abismo a voluntad.",
    powers_en: "Followers of Lugonu gain powers to depart the Abyss at will, to banish monsters there, and to flee back inside when needed. Lugonu will also banish nearby foes if any other god attempts to interfere with their followers. Later, followers will be able to corrupt the ordered world, opening a gate for creatures of the Abyss to pass through, and to gate themselves directly into this realm of chaos. Lugonu will protect followers who unwield weapons imbued with the distorting energies of the Abyss, and eventually will offer to distort a follower's melee weapon. Lugonu expects followers to spread unceasing chaos in the overworld, and as such does not grant piety to worshippers while they remain in the Abyss itself.",
    powers_es_mt: "Los seguidores de Lugonu obtienen poderes para salir del Abismo a voluntad, desterrar monstruos allí y refugiarse dentro cuando sea necesario. Lugonu también desterrará a los enemigos cercanos si cualquier otro dios intenta interferir con sus seguidores. Más tarde, los seguidores podrán corromper el mundo ordenado, abriendo un portal para que las criaturas del Abismo pasen a través, y transportarse directamente a este reino del caos. Lugonu protegerá a los seguidores que empuñen armas imbuidas con las energías distorsionadoras del Abismo, y eventualmente ofrecerá distorsionar el arma cuerpo a cuerpo de un seguidor. Lugonu espera que los seguidores extiendan un caos incesante en el mundo superior, y por lo tanto no concede piedad a los adoradores mientras permanezcan en el Abismo mismo.",
    wrath_en: "Lugonu's ire renders the barrier between reality and the Abyss weak and permeable. Space warps, hurling victims across the dungeon, or even directly into the Abyss. Lugonu also reaches out and sends the chaotic inhabitants of the Abyss against victims, with veteran adventurers facing the greatest horrors of the Abyss. Lugonu does not forgive easily, and will not allow ex-worshippers to rejoin the fold while Lugonu's wrath still lasts.",
    wrath_es_mt: "La ira de Lugonu vuelve la barrera entre la realidad y el Abismo débil y permeable. El espacio se deforma, arrojando a las víctimas a través de la mazmorra, o incluso directamente al Abismo. Lugonu también extiende su mano y envía a los caóticos habitantes del Abismo contra las víctimas, enfrentando a los aventureros veteranos con los mayores horrores del Abismo. Lugonu no perdona fácilmente, y no permitirá que los ex adoradores se reincorporen mientras dure su ira."
  },
  Makhleb: {
    description_en: "Makhleb the Destroyer is a fearsome deity of bloodshed and mortification of the flesh. Followers are expected to cleanse others by inflicting suffering and death on them in Makhleb's name. Dedicated followers may also access the raw energies and hell-spawned servants of chaos, so that they may better break the impure world and its false laws for their evil god's glory.",
    description_es_mt: "Makhleb el Destructor es una temible deidad del derramamiento de sangre y la mortificación de la carne. Se espera que los seguidores purifiquen a otros infligiéndoles sufrimiento y muerte en nombre de Makhleb. Los seguidores dedicados también pueden acceder a las energías primigenias y a los sirvientes del caos nacidos en el infierno, para que puedan destruir mejor el mundo impuro y sus falsas leyes para la gloria de su malvado dios.",
    powers_en: "Makhleb offers followers the ability to unleash bolts of chaotic destruction at the cost of their own health as well as call in help from powerful (if sometimes uncooperative) demons. The most devoted of worshippers will eventually be gifted with knowledge of Infernal Marks, allowing them to ritually brand their own bodies in exchange for one of the Destroyer's many hellish powers. Makhleb's powers all come with a price in blood. However, Makhleb will grant followers renewed health in return for killing beings of all kinds.",
    powers_es_mt: "Makhleb ofrece a sus seguidores la capacidad de lanzar rayos de destrucción caótica a costa de su propia salud, así como pedir ayuda de poderosos demonios (a veces poco cooperativos). Los adoradores más devotos recibirán eventualmente el conocimiento de las Marcas Infernales, permitiéndoles marcar ritualmente sus propios cuerpos a cambio de uno de los muchos poderes infernales del Destructor. Todos los poderes de Makhleb tienen un precio en sangre. Sin embargo, Makhleb concederá a los seguidores salud renovada a cambio de matar seres de todo tipo.",
    wrath_en: "Those who invite the fury of Makhleb are buried in demons and destruction. The greatest punishments are reserved for the strongest sinners; crystal spears and Executioners are hurled with abandon only at those Makhleb finds truly deserving!",
    wrath_es_mt: "Quienes inviten la furia de Makhleb serán sepultados en demonios y destrucción. Los mayores castigos están reservados para los pecadores más fuertes; lanzas de cristal y Verdugos son lanzados sin piedad solo contra aquellos que Makhleb considera verdaderamente merecedores."
  },
  NemelexXobeh: {
    description_en: "Nemelex is a strange and unpredictable chaotic trickster god, whose powers are invoked through magical packs of cards painted in the ichor of demons. Followers will be granted decks of cards as they traverse the dungeon, and are encouraged to trust in the cards to provide them with divine assistance. However, the Trickster can also ensure that fortune favours the bold.",
    description_es_mt: "Nemelex es un extraño e impredecible dios tramposo del caos, cuyos poderes se invocan a través de mazos de cartas mágicas pintadas con el icor de los demonios. Los seguidores recibirán barajas de cartas mientras recorren la mazmorra, y se les anima a confiar en que las cartas les proporcionarán asistencia divina. Sin embargo, el Tramposo también puede asegurarse de que la fortuna favorezca a los audaces.",
    powers_en: "The Trickster's followers gain various ways to influence fate when playing their cards. The effects of the cards will be more powerful with higher piety and with greater Invocations skill. Later, followers will gain powerful abilities to manipulate the cards, allowing them to choose one of three drawn cards, to gain the effects of multiple cards at once, and finally to stack decks and re-order their contents.",
    powers_es_mt: "Los seguidores del Tramposo ganan varias formas de influir en el destino al jugar sus cartas. Los efectos de las cartas serán más poderosos con mayor piedad y con mayor habilidad de Invocaciones. Más tarde, los seguidores obtendrán poderosas habilidades para manipular las cartas, permitiéndoles elegir una de tres cartas robadas, obtener los efectos de múltiples cartas a la vez y finalmente apilar los mazos y reordenar su contenido.",
    wrath_en: "Those who abandon Nemelex Xobeh have all of their gifted decks revoked immediately. They are also regularly forced to draw from the deck of Punishment, inflicting a range of unpleasant effects including draining, torment and polymorphing, as well as calling upon other gods to assist in inflicting wrath.",
    wrath_es_mt: "Quienes abandonen a Nemelex Xobeh verán revocados todos sus mazos regalados inmediatamente. También se ven obligados regularmente a robar del mazo de Castigo, sufriendo una variedad de efectos desagradables que incluyen drenaje, tormento y polimorfia, además de invocar a otros dioses para ayudar a infligir ira."
  },
  Okawaru: {
    description_en: "Okawaru is a dangerous and powerful god of battle. Followers are expected to constantly prove themselves in combat, and may channel Okawaru's might to enhance their prowess. Okawaru demands that followers prove themselves by their own strength alone, and so worshippers are forbidden from gaining allies by any means. Okawaru pays little heed to easy victories, but will reward worshippers for heroic feats against mighty foes.",
    description_es_mt: "Okawaru es un peligroso y poderoso dios de la batalla. Se espera que los seguidores se prueben constantemente en combate y pueden canalizar el poder de Okawaru para mejorar su destreza. Okawaru exige que los seguidores se demuestren por su propia fuerza, por lo que los adoradores tienen prohibido obtener aliados por cualquier medio. Okawaru presta poca atención a las victorias fáciles, pero recompensará a los adoradores por hazañas heroicas contra enemigos poderosos.",
    powers_en: "Followers of Okawaru will gain the ability to temporarily increase their skills in combat, and, much later, to deal much faster blows. Okawaru will eventually gift followers with ammunition, weapons and armour. The most favoured of Okawaru may challenge their foes to honourable single combat.",
    powers_es_mt: "Los seguidores de Okawaru obtendrán la capacidad de aumentar temporalmente sus habilidades en combate y, mucho más tarde, de asestar golpes mucho más rápidos. Okawaru eventualmente regalará a sus seguidores munición, armas y armadura. Los más favorecidos de Okawaru pueden desafiar a sus enemigos a un combate singular honorable.",
    wrath_en: "Okawaru's most vicious warriors are sent against rebellious servants. Novices find themselves swarmed by packs of ogres and gnolls, while champions are surrounded by titans and elvish blademasters.",
    wrath_es_mt: "Los guerreros más violentos de Okawaru son enviados contra los sirvientes rebeldes. Los novatos se ven acosados por manadas de ogros y gnolls, mientras que los campeones son rodeados por titanes y maestros espadachines élficos."
  },
  Pakellas: {
    description_en: "Pakellas the Inventive believes in the supremacy of devices, magical or otherwise, over spells and other forms of magic. Followers, although cut off from ambient magical power, are provided with magical energy to empower their devices so long as they use them to assert Pakellas' supremacy. Pakellas will grant devout worshippers access to increasingly powerful devices.",
    description_es_mt: "Pakellas el Inventivo cree en la supremacía de los dispositivos, mágicos o no, sobre los hechizos y otras formas de magia. Los seguidores, aunque están aislados del poder mágico ambiental, reciben energía mágica para potenciar sus dispositivos siempre que los usen para afirmar la supremacía de Pakellas. Pakellas concederá a los devotos adoradores acceso a dispositivos cada vez más poderosos.",
    powers_en: "Followers of Pakellas do not regenerate their magic power naturally, and are forbidden from using external means to do so; instead, they are granted magical energy on killing beings. They may use increasing amounts of magical energy to strengthen their devices, temporarily granting them additional power, and can also use their magical energy to recharge their devices. Sufficiently devout followers will receive new devices from Pakellas, and may eventually petition Pakellas to personally charge one of their devices beyond its normal limits.",
    powers_es_mt: "Los seguidores de Pakellas no regeneran su poder mágico de forma natural y tienen prohibido usar medios externos para hacerlo; en su lugar, reciben energía mágica al matar seres. Pueden usar cantidades crecientes de energía mágica para fortalecer sus dispositivos, otorgándoles temporalmente poder adicional, y también pueden usar su energía mágica para recargar sus dispositivos. Los seguidores suficientemente devotos recibirán nuevos dispositivos de Pakellas, y eventualmente pueden solicitar a Pakellas que cargue personalmente uno de sus dispositivos más allá de sus límites normales.",
    wrath_en: "Those that offend Pakellas will find themselves completely unable to make use of their devices for the duration of Pakellas' displeasure. Those who abandon Pakellas altogether will also continue to be unable to regenerate their magical power so long as Pakellas' attention remains on them.",
    wrath_es_mt: "Quienes ofendan a Pakellas se encontrarán completamente incapaces de usar sus dispositivos mientras dure el descontento de Pakellas. Quienes abandonen a Pakellas por completo también seguirán siendo incapaces de regenerar su poder mágico mientras la atención de Pakellas permanezca sobre ellos."
  },
  Qazlal: {
    description_en: "Qazlal Stormbringer is a violent god of tempests, who delights in unleashing the forces of nature against the unsuspecting. Those who invite Qazlal's gaze will find themselves the eye in a storm of elemental destruction, from which only their God can protect them. Pious worshippers of Qazlal will gain the ability to direct and control the destructive might of the storm.",
    description_es_mt: "Qazlal Tormenta es un violento dios de las tempestades, que se deleita desatando las fuerzas de la naturaleza contra los desprevenidos. Quienes inviten la mirada de Qazlal se encontrarán en el ojo de una tormenta de destrucción elemental, de la cual solo su dios puede protegerlos. Los piadosos adoradores de Qazlal ganarán la capacidad de dirigir y controlar el poder destructivo de la tormenta.",
    powers_en: "Followers of Qazlal are protected from all clouds. As a follower of Qazlal gains divine favour, they are slowly surrounded by a loud storm. In addition to generating noise, the storm causes elemental clouds to appear near followers, blocks attacks, and (for the particularly devout) deflects incoming projectiles. Qazlal allows followers to incite nature against their foes, causing a localised natural disturbance or, for particularly devout followers, a more widespread disaster. Followers of Qazlal eventually gain temporary resistances after taking damage, and can give life to clouds, turning them into allied elementals.",
    powers_es_mt: "Los seguidores de Qazlal están protegidos de todas las nubes. A medida que un seguidor de Qazlal gana favor divino, es rodeado lentamente por una tormenta ruidosa. Además de generar ruido, la tormenta hace que aparezcan nubes elementales cerca de los seguidores, bloquea ataques y (para los particularmente devotos) desvía proyectiles entrantes. Qazlal permite a los seguidores incitar a la naturaleza contra sus enemigos, causando una perturbación natural localizada o, para los seguidores particularmente devotos, un desastre más extendido. Los seguidores de Qazlal obtienen eventualmente resistencias temporales después de recibir daño, y pueden dar vida a las nubes, convirtiéndolas en elementales aliados.",
    wrath_en: "Qazlal's wrath is swift and unmistakable. Sinners are stripped of their resistances and assaulted by furious elemental creatures, and Qazlal will create mighty thunderclaps to alert their foes.",
    wrath_es_mt: "La ira de Qazlal es rápida e inconfundible. Los pecadores son despojados de sus resistencias y asaltados por furiosas criaturas elementales, y Qazlal creará poderosos truenos para alertar a sus enemigos."
  },
  Ru: {
    description_en: "Of all the gods, only Ru opposed creation. Not as folly, but as distraction. Initiates of Ru can open channels to the powers underlying the visible world by renouncing the fetters that bind them here. These sacrifices are not made to Ru, but rather given up freely and permanently. Having made such sacrifices, initiates will become able to draw upon this immense power to aid themselves, eventually gaining the ability to unleash its destructive might against their foes.",
    description_es_mt: "De todos los dioses, solo Ru se opuso a la creación. No como una locura, sino como distracción. Los iniciados de Ru pueden abrir canales a los poderes subyacentes del mundo visible renunciando a las ataduras que los sujetan aquí. Estos sacrificios no se hacen a Ru, sino que se entregan libre y permanentemente. Habiendo hecho tales sacrificios, los iniciados podrán aprovechar este inmenso poder para ayudarse a sí mismos, ganando eventualmente la capacidad de desatar su poder destructivo contra sus enemigos.",
    powers_en: "Ru will offer followers a number of sacrifices as they travel the dungeon. On accepting these sacrifices, followers will gradually gain an aura of immense power. This aura will initially cause foes that attempt to harm them to falter and become stricken with maladies. After making further sacrifices, followers will be able to draw on this power to restore their health and magic, or to make a lightning-fast explosive leap. Exceptional sacrificants can unleash their power in a massive strike against all their foes. Each of the powers of Ru's sacrificants increases in strength with more piety from more sacrifices.",
    powers_es_mt: "Ru ofrecerá a sus seguidores una serie de sacrificios mientras viajan por la mazmorra. Al aceptar estos sacrificios, los seguidores ganarán gradualmente un aura de inmenso poder. Este aura inicialmente hará que los enemigos que intenten dañarlos flaqueen y sean afligidos por enfermedades. Después de hacer más sacrificios, los seguidores podrán aprovechar este poder para restaurar su salud y magia, o para realizar un salto explosivo relámpago. Los sacrificantes excepcionales pueden desatar su poder en un golpe masivo contra todos sus enemigos. Cada uno de los poderes de los sacrificantes de Ru aumenta en fuerza con más piedad de más sacrificios.",
    wrath_en: "Those who leave Ru's service will not receive any further punishment; however, their piety will be lost even upon rejoining, and their sacrifices remain forever.",
    wrath_es_mt: "Quienes abandonen el servicio de Ru no recibirán ningún castigo adicional; sin embargo, su piedad se perderá incluso al reincorporarse, y sus sacrificios permanecerán para siempre."
  },
  SifMuna: {
    description_en: "Sif Muna the Loreminder is a contemplative but powerful deity, served by those who seek magical knowledge. Followers who tirelessly pursue new horizons can call upon the Loreminder for magical power and the ability to cast spells beyond their magical training. The devout are rewarded with a supply of spellbooks taken directly from Sif Muna's legendary library.",
    description_es_mt: "Sif Muna la Sabia es una deidad contemplativa pero poderosa, servida por aquellos que buscan conocimiento mágico. Los seguidores que persiguen incansablemente nuevos horizontes pueden invocar a la Sabia para obtener poder mágico y la capacidad de lanzar hechizos más allá de su entrenamiento mágico. Los devotos son recompensados con un suministro de libros de hechizos tomados directamente de la legendaria biblioteca de Sif Muna.",
    powers_en: "Sif Muna grants followers the ability to rapidly restore their magical energy, and to forget spells at will, so as to learn new ones. Worshippers can call upon the Loreminder to help cast any spell they've discovered, even if it's well beyond their current magical training. Over time, devout followers will receive spellbooks containing a vast range of spells.",
    powers_es_mt: "Sif Muna concede a sus seguidores la capacidad de restaurar rápidamente su energía mágica y de olvidar hechizos a voluntad para aprender otros nuevos. Los adoradores pueden invocar a la Sabia para que les ayude a lanzar cualquier hechizo que hayan descubierto, incluso si está mucho más allá de su entrenamiento mágico actual. Con el tiempo, los devotos seguidores recibirán libros de hechizos que contienen una amplia gama de conjuros.",
    wrath_en: "Those in Sif Muna's ill graces find the very forces of magic rebelling against them. They are confused and stupefied, their magical reserves drained, their enchantments unravelled. Casting spells, too, becomes unreliable – and even dangerous.",
    wrath_es_mt: "Aquellos que están en desgracia con Sif Muna descubren que las propias fuerzas de la magia se rebelan contra ellos. Están confundidos y aturdidos, sus reservas mágicas drenadas, sus encantamientos deshechos. Lanzar hechizos también se vuelve poco fiable, e incluso peligroso."
  },
  theShiningOne: {
    description_en: "Followers of the Shining One are bound to the code of the honourable warrior, soldiers in their god's eternal crusade against evil. For forsaking dark magic and underhanded tactics, the Shining One rewards them and their allies with the power they need to slay demons and the undead. Especially devout warriors can even call upon angels in times of need. The Shining One's followers can convert to Elyvilon or Zin while keeping some piety.",
    description_es_mt: "Los seguidores del Resplandeciente están sujetos al código del guerrero honorable, soldados en la cruzada eterna de su dios contra el mal. Por renunciar a la magia oscura y las tácticas engañosas, el Resplandeciente los recompensa a ellos y a sus aliados con el poder que necesitan para matar demonios y no muertos. Los guerreros especialmente devotos pueden incluso invocar ángeles en momentos de necesidad. Los seguidores del Resplandeciente pueden convertirse a Elyvilon o Zin conservando algo de piedad.",
    powers_en: "Followers of the Shining One are surrounded by a halo that reveals their enemies to them. Followers will gain power by killing evil beings, and with growing piety their life force will be protected. The Shining One will keep summoned and charmed allies on their side longer, should the allies prove worthy of the crusade. Followers will gain use of a divine shield to protect them in battle. Later, they can channel blasts of cleansing flame that are particularly damaging to unholy beings, and can call upon powerful divine beings as temporary allies. Highly pious followers may request the Shining One's blessing upon a weapon. The Shining One may occasionally directly intervene to save a follower's life.",
    powers_es_mt: "Los seguidores del Resplandeciente están rodeados por un halo que revela a sus enemigos. Los seguidores ganarán poder matando seres malignos, y con el aumento de la piedad su fuerza vital será protegida. El Resplandeciente mantendrá a los aliados invocados y encantados a su lado por más tiempo, si los aliados demuestran ser dignos de la cruzada. Los seguidores obtendrán un escudo divino para protegerlos en la batalla. Más tarde, pueden canalizar ráfagas de llama purificadora que dañan particularmente a los seres impíos, y pueden invocar poderosos seres divinos como aliados temporales. Los seguidores muy piadosos pueden solicitar la bendición del Resplandeciente sobre un arma. El Resplandeciente puede ocasionalmente intervenir directamente para salvar la vida de un seguidor.",
    wrath_en: "The Shining One's wrath is straightforward and unmistakable. Its victims find themselves smitten with holy fire and beset with holy warriors. Sinners will be silenced, and the Shining One will also shout to alert the victim's foes.",
    wrath_es_mt: "La ira del Resplandeciente es directa e inconfundible. Sus víctimas se encuentran golpeadas por fuego sagrado y acosadas por guerreros santos. Los pecadores serán silenciados, y el Resplandeciente también gritará para alertar a los enemigos de la víctima."
  },
  Trog: {
    description_en: "Trog is an ancient god of anger and violence. Followers are expected to kill in Trog's name, and especially to slay wizards. In return, worshippers of Trog gain the ability to go berserk at will in combat, and will be granted assistance in the form of powerful weapons and mighty allies. Followers are absolutely forbidden the use of spell magic.",
    description_es_mt: "Trog es un antiguo dios de la ira y la violencia. Se espera que los seguidores maten en nombre de Trog, y especialmente que eliminen hechiceros. A cambio, los adoradores de Trog obtienen la capacidad de enfurecerse a voluntad en combate y recibirán asistencia en forma de armas poderosas y aliados formidables. Los seguidores tienen absolutamente prohibido el uso de magia de hechizos.",
    powers_en: "Trog offers various powers to help followers in battle. Followers will gain the ability to go berserk at will, and Trog will extend the duration of their berserk rage on killing foes. Trog will grant followers the ability to rapidly heal their wounds while fortifying their willpower, and later the ability to call in powerful raging allies. Eventually, Trog will gift followers with weapons, often with antimagic effects.",
    powers_es_mt: "Trog ofrece varios poderes para ayudar a los seguidores en la batalla. Los seguidores obtendrán la capacidad de enfurecerse a voluntad, y Trog extenderá la duración de su furia berserker al matar enemigos. Trog concederá a los seguidores la capacidad de curar rápidamente sus heridas mientras fortalece su fuerza de voluntad, y más tarde la capacidad de invocar poderosos aliados enfurecidos. Eventualmente, Trog regalará a los seguidores armas, a menudo con efectos antimagia.",
    wrath_en: "Trog's wrath is incandescent. Offenders find themselves swarmed by berserkers – from packs of bears to, for the most powerful, mobs of giants and trolls. Otherwise, those who anger Trog will regularly lose both their strength and self-control as they thoughtlessly thrash in place.",
    wrath_es_mt: "La ira de Trog es incandescente. Los infractores se ven acosados por berserkers, desde manadas de osos hasta, para los más poderosos, turbas de gigantes y trolls. Por lo demás, quienes enfurecen a Trog perderán regularmente tanto su fuerza como su autocontrol, sacudiéndose sin sentido en su lugar."
  },
  Uskayaw: {
    description_en: "Uskayaw the Reveller is a god of ecstatic dance. In the dungeon, Uskayaw appreciates the passion and rhythm of combat, rewarding followers for each strike they deliver and for the damage they deal their foes. The longer the dance continues, the greater powers Uskayaw offers. When the dance ends, Uskayaw quickly loses interest.",
    description_es_mt: "Uskayaw el Fiestero es un dios de la danza extática. En la mazmorra, Uskayaw aprecia la pasión y el ritmo del combate, recompensando a los seguidores por cada golpe que asestan y por el daño que infligen a sus enemigos. Cuanto más dura la danza, mayores poderes ofrece Uskayaw. Cuando la danza termina, Uskayaw pierde rápidamente el interés.",
    powers_en: "Worshippers of Uskayaw can stomp to damage foes around them, and rapidly move through a line of creatures while confusing them. When a worshipper's dance reaches a certain point, Uskayaw will immediately stop all foes so that the dancer may take a solo. As the dance continues, Uskayaw will link the emotions of foes, forcing them to share their pain. The duration of these effects will increase with Invocations skill, and as long as the intensity of the dance is sufficient they may be repeated after a short time. If the dance continues further, Uskayaw allows worshippers to end it by melding with and then violently exploding from a foe, killing it instantly.",
    powers_es_mt: "Los adoradores de Uskayaw pueden pisotear para dañar a los enemigos a su alrededor y moverse rápidamente a través de una línea de criaturas mientras las confunden. Cuando la danza de un adorador alcanza cierto punto, Uskayaw detendrá inmediatamente a todos los enemigos para que el bailarín pueda hacer un solo. A medida que la danza continúa, Uskayaw vinculará las emociones de los enemigos, obligándolos a compartir su dolor. La duración de estos efectos aumentará con la habilidad de Invocaciones, y mientras la intensidad de la danza sea suficiente, pueden repetirse después de un breve tiempo. Si la danza continúa aún más, Uskayaw permite a los adoradores terminarla fusionándose con un enemigo y luego explotando violentamente, matándolo al instante.",
    wrath_en: "Uskayaw's wrath turns the powers of the dance against the offender. The prude will find their foes going berserk and will be forced to helplessly watch as foes execute their own solos. When the dance is getting too slow, Uskayaw will cause noise to attract more revellers.",
    wrath_es_mt: "La ira de Uskayaw vuelve los poderes de la danza contra el infractor. El aguafiestas verá a sus enemigos enfurecerse y se verá obligado a observar impotente cómo los enemigos ejecutan sus propios solos. Cuando la danza se vuelve demasiado lenta, Uskayaw causará ruido para atraer a más fiesteros."
  },
  Vehumet: {
    description_en: "Vehumet is a god of the destructive powers of magic. Followers will gain divine assistance in commanding the hermetic arts, and the most favoured stand to gain access to some of the fearsome spells in Vehumet's library. One's devotion to Vehumet can be proven by the causing of as much carnage and destruction as possible.",
    description_es_mt: "Vehumet es un dios de los poderes destructivos de la magia. Los seguidores obtendrán asistencia divina en el dominio de las artes hermética, y los más favorecidos obtendrán acceso a algunos de los temibles hechizos de la biblioteca de Vehumet. La devoción a Vehumet se demuestra causando tanta carnicería y destrucción como sea posible.",
    powers_en: "Worshippers of Vehumet will quickly be able to recover their magical energy upon killing beings. As they gain favour, they will also gain enhancements to their destructive spells — first assistance in casting such spells and then increased range for conjurations. Vehumet will offer followers the knowledge of increasingly powerful destructive spells as they gain piety.",
    powers_es_mt: "Los adoradores de Vehumet podrán recuperar rápidamente su energía mágica al matar seres. A medida que ganan favor, también obtendrán mejoras en sus hechizos destructivos: primero asistencia al lanzar tales hechizos y luego mayor alcance para las conjuraciones. Vehumet ofrecerá a los seguidores el conocimiento de hechizos destructivos cada vez más poderosos a medida que ganan piedad.",
    wrath_en: "Those that anger Vehumet find destruction amply heaped upon them. Novices are struck by flame and frost; archmages by crystal spears and firestorms. Their own conjurations, too, are wont to misfire at the worst possible moments.",
    wrath_es_mt: "Quienes enfurecen a Vehumet descubren que la destrucción se acumula sobre ellos. Los novatos son golpeados por llamas y escarcha; los archimagos por lanzas de cristal y tormentas de fuego. Sus propias conjuraciones también tienden a fallar en los peores momentos posibles."
  },
  WuJian: {
    description_en: "The Wu Jian Council is a congregation of martial monks, ascended to divinity after battling their way out of the afterlife. Disciples of the Council are able to execute acrobatic martial maneuvers, such as wall jumps, spinning attacks and punishing lunges. They will eventually become able to request help in the form of a storm of heavenly clouds.",
    description_es_mt: "El Consejo Wu Jian es una congregación de monjes marciales, ascendidos a la divinidad después de abrirse camino luchando para salir del más allá. Los discípulos del Consejo pueden ejecutar maniobras marciales acrobáticas, como saltos de pared, ataques giratorios y estocadas castigadoras. Eventualmente podrán solicitar ayuda en forma de una tormenta de nubes celestiales.",
    powers_en: "Disciples of the Council learn to perform three martial techniques while moving around in combat. They will also be taught to move at unfathomable speeds for short distances, and become able to summon a storm of golden clouds to increase their precision and damage for as long as they keep using martial attacks.",
    powers_es_mt: "Los discípulos del Consejo aprenden a realizar tres técnicas marciales mientras se mueven en combate. También se les enseña a moverse a velocidades inconcebibles en distancias cortas, y se vuelven capaces de invocar una tormenta de nubes doradas para aumentar su precisión y daño mientras sigan usando ataques marciales.",
    wrath_en: "Those who turn against the Council must be prepared to endure death by a thousand cuts. No hiding place is secure, no disguise perfect enough to avoid the sudden spring of traps, the flying daggers and the armies of animated weapons that will ambush the betrayer.",
    wrath_es_mt: "Quienes se vuelvan contra el Consejo deben estar preparados para soportar la muerte por mil cortes. Ningún escondite es seguro, ningún disfraz es lo suficientemente perfecto para evitar la repentina activación de trampas, las dagas voladoras y los ejércitos de armas animadas que emboscarán al traidor."
  },
  Xom: {
    description_en: "Xom is a wild and unpredictable god of chaos, who seeks not worshippers but playthings with which to toy. Many choose to follow Xom in the hope of receiving fabulous rewards and mighty powers, but Xom is nothing if not capricious. There is nothing a follower can do to influence Xom's mood.",
    description_es_mt: "Xom es un dios salvaje e impredecible del caos, que no busca adoradores sino juguetes con los que jugar. Muchos eligen seguir a Xom con la esperanza de recibir fabulosas recompensas y poderosos dones, pero Xom es extremadamente caprichoso. No hay nada que un seguidor pueda hacer para influir en el humor de Xom.",
    powers_en: "To worship Xom is to live riskily. In a good mood Xom may shower worshippers with gifts, while at other times this capricious god could decide to \"spice things up a little\" and send worshippers to their doom. If such toys of Xom prove to be interesting, so much the better; if not, well, there'll be other playthings...",
    powers_es_mt: "Adorar a Xom es vivir peligrosamente. De buen humor, Xom puede colmar a los adoradores de regalos, mientras que en otras ocasiones este dios caprichoso podría decidir «animar las cosas un poco» y enviar a los adoradores a su perdición. Si tales juguetes de Xom resultan ser interesantes, tanto mejor; si no, bueno, habrá otros juguetes...",
    wrath_en: "Unfaithful ex-followers will find themselves suffering through Xom's bad moods for so long as Xom can be bothered to remember about them. Still, Xom's caprice remains; the unfaithful are rewarded just as the faithful are punished.",
    wrath_es_mt: "Los ex seguidores infieles se encontrarán sufriendo los malos humores de Xom mientras a Xom le importe recordarlos. Aun así, el capricho de Xom permanece; los infieles son recompensados al igual que los fieles son castigados."
  },
  Yredelemnul: {
    description_en: "Cast down by the good gods eons ago, Yredelemnul seeks to despoil their creations and chain all living souls within their inexorable grip. Followers who would conquer in Yredelemnul's name are granted the power to reap an army of the dead and bind powerful souls into eternal service - provided they can sweep across the land in a tide as inexorable as their god.",
    description_es_mt: "Derribado por los dioses buenos hace eones, Yredelemnul busca despojar sus creaciones y encadenar a todas las almas vivientes en su grip inexorable. Los seguidores que conquisten en nombre de Yredelemnul reciben el poder de cosechar un ejército de muertos y atar almas poderosas al servicio eterno, siempre que puedan barrer la tierra en una marea tan inexorable como su dios.",
    powers_en: "Followers of Yredelemnul carry the Black Torch, allowing them to gather souls and surround themselves in darkness. They can raise foes who die in the light of the torch as mindless servants, hurl torchlight to scour the living and empower the dead, and bind especially noteworthy souls to fight for them in death with the full capacities they held in life. Especially devout worshippers can even call down the inescapable grip of the Fallen directly, binding foes helplessly in place as the very life is sucked from them. Yredelemnul will also dispatch undead servants to aid followers at the start of each new conquest.",
    powers_es_mt: "Los seguidores de Yredelemnul portan la Antorcha Negra, que les permite reunir almas y rodearse de oscuridad. Pueden levantar a los enemigos que mueren a la luz de la antorcha como sirvientes sin mente, arrojar luz de antorcha para quemar a los vivos y empoderar a los muertos, y atar almas especialmente notables para que luchen por ellos en la muerte con todas las capacidades que tenían en vida. Los adoradores especialmente devotos pueden incluso invocar directamente el grip ineludible del Caído, inmovilizando a los enemigos mientras la vida misma es succionada de ellos. Yredelemnul también enviará sirvientes no muertos para ayudar a los seguidores al comienzo de cada nueva conquista.",
    wrath_en: "Those who anger Yredelemnul find themselves beset by legions of the dead. Sometimes, the god will also intervene directly, binding the unfaithful in inescapable chains as Yredelemnul's dark army demonstrates the price of betrayal.",
    wrath_es_mt: "Quienes enfurecen a Yredelemnul se ven acosados por legiones de muertos. A veces, el dios también interviene directamente, atando a los infieles con cadenas ineludibles mientras el oscuro ejército de Yredelemnul demuestra el precio de la traición."
  },
  Zin: {
    description_en: "Zin is a god of discipline. Followers must remain pure of body and soul, refraining from dark magic and chaotic acts. They must also tithe a fraction of all gold gained, preferably followed by donations of more. In exchange, worshippers may invoke Zin's wrath upon sinners, and eventually gain various divine protections. Zin's followers can convert to Elyvilon or the Shining One while keeping some piety.",
    description_es_mt: "Zin es un dios de la disciplina. Los seguidores deben permanecer puros de cuerpo y alma, absteniéndose de la magia oscura y los actos caóticos. También deben diezmar una fracción de todo el oro ganado, preferiblemente seguido de donaciones de más. A cambio, los adoradores pueden invocar la ira de Zin sobre los pecadores y eventualmente obtener varias protecciones divinas. Los seguidores de Zin pueden convertirse a Elyvilon o al Resplandeciente conservando algo de piedad.",
    powers_en: "Zin grants followers the ability to preach to the unenlightened masses, and powers to vitalise their bodies, protecting them from various afflictions. Later, followers gain the ability to imprison their foes temporarily. Followers can eventually find temporary safety in a divine refuge. As piety grows, followers will be protected from mutation and the Hells, and Zin may even occasionally directly intervene to save a follower's life.",
    powers_es_mt: "Zin concede a los seguidores la capacidad de predicar a las masas no ilustradas y poderes para vitalizar sus cuerpos, protegiéndolos de diversas aflicciones. Más tarde, los seguidores obtienen la capacidad de aprisionar temporalmente a sus enemigos. Los seguidores pueden eventualmente encontrar seguridad temporal en un refugio divino. A medida que la piedad crece, los seguidores serán protegidos de la mutación y los Infiernos, y Zin puede incluso ocasionalmente intervenir directamente para salvar la vida de un seguidor.",
    wrath_en: "Those under Zin's wrath will find their beneficial mutations stripped away, their enemies alerted, and their senses confounded by the axioms of Law; confusion, fainting, blindness and complete paralysis will be their lot.",
    wrath_es_mt: "Aquellos bajo la ira de Zin verán sus mutaciones beneficiosas eliminadas, sus enemigos alertados y sus sentidos confundidos por los axiomas de la Ley; la confusión, el desmayo, la ceguera y la parálisis completa serán su destino."
  }
}

function getFieldKey(godName, section, lang) {
  const key = godName.replace(/[^a-zA-Z0-9]/g, '')
  return `${section}_${lang}`
}

function processGod(filePath) {
  const raw = readFileSync(filePath, 'utf-8')
  const god = JSON.parse(raw)
  const key = god.name.replace(/[^a-zA-Z0-9]/g, '')
  const t = translations[key]
  if (!t) {
    console.error(`No translations for ${god.name} (key: ${key})`)
    return
  }

  for (const section of ['description', 'powers', 'wrath']) {
    const enKey = `${section}_en`
    const esMtKey = `${section}_es_mt`
    if (god[section].en !== t[enKey]) {
      console.error(`EN mismatch for ${god.name}/${section}`)
      return
    }
    god[section].es_mt = t[esMtKey]
  }

  writeFileSync(filePath, JSON.stringify(god, null, 2) + '\n')
  console.log(`Updated ${god.name}`)
}

const files = readdirSync(godsDir).filter(f => f.endsWith('.json'))
for (const file of files) {
  processGod(join(godsDir, file))
}

console.log('Done!')
